cypress_script:
describe('Select Menu Widgets', () => {
  it('should select a color successfully', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#oldSelectMenu').select('Red');
    cy.get('#oldSelectMenu').should('have.value', 'red');
  });

  it('should not change the URL on empty selection', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('#oldSelectMenu').select('');
    cy.url().should('eq', 'https://demoqa.com/select-menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Select Menu Widgets', () => {
  test('should select a color successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#oldSelectMenu', 'red');
    const selectedValue = await page.locator('#oldSelectMenu').inputValue();
    expect(selectedValue).toBe('red');
  });

  test('should not change the URL on empty selection', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('#oldSelectMenu', '');
    expect(page.url()).toBe('https://demoqa.com/select-menu');
  });
});
